const input=$json??{}; const event=input.event??input;
const dealId=event.deal_id??event.dealId, leadId=event.lead_id??event.leadId, propertyId=event.property_id??event.propertyId;
const provider=String(event.provider??event.provider_name??'').trim();
const providerMessageId=String(event.provider_message_id??event.message_id??'').trim();
const channel=String(event.channel??'').toLowerCase();
const dispatchStatus=String(event.dispatch_status??event.status??'').toLowerCase();
const dnc=Boolean(event.dnc??event.do_not_contact), blockers=Array.isArray(event.blockers)?event.blockers:[];
const baseKey=String(event.idempotency_key??[dealId,leadId,propertyId,'seller-followup'].filter(Boolean).join(':')).trim();
const confirmationKey=baseKey+':provider-confirmation:'+providerMessageId;
let route='WF-355',decision='confirmation_pending',reason='awaiting_provider_receipt';
if(dnc){route='WF-126';decision='dnc_hard_stop';reason='dnc_or_opt_out';}
else if(blockers.length){route='WF-126';decision='blocked';reason='operational_blocker';}
else if(!dealId||!leadId||!propertyId||!baseKey){route='WF-359';decision='identity_or_idempotency_missing';reason='required_identity_missing';}
else if(!provider||!providerMessageId){route='WF-359';decision='provider_confirmation_identity_missing';reason='provider_or_message_id_missing';}
else if(['sent','accepted','queued'].includes(dispatchStatus)){route='WF-355';decision='provider_dispatch_confirmed';reason='provider_accepted_dispatch';}
else if(['delivered'].includes(dispatchStatus)){route='WF-349';decision='delivery_confirmed';reason='provider_delivered';}
else if(['failed','bounced','rejected','undeliverable'].includes(dispatchStatus)){route='WF-350';decision='delivery_failed';reason='provider_delivery_failure';}
else if(event.inbound_response||['reply','received','seller_response'].includes(dispatchStatus)){route='WF-342';decision='seller_response_received';reason='inbound_response';}
else {route='WF-355';decision='confirmation_pending';reason='unclassified_provider_state';}
return [{json:{...event,workflow:'WF-360',decision,reason,route,deal_id:dealId,lead_id:leadId,property_id:propertyId,provider,provider_message_id:providerMessageId,channel,dispatch_status:dispatchStatus,idempotency_key:baseKey,confirmation_idempotency_key:confirmationKey,audit_event:'provider_dispatch_confirmation_crm_persistence'}}];
